CREATE TABLE IF NOT EXISTS `huoniao_article` (`id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT, `aid` INT(10) UNSIGNED NOT NULL COMMENT '信息ID', `body` MEDIUMTEXT NOT NULL COMMENT '信息内容', PRIMARY KEY (`id`), KEY `aid` (`aid`)) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='新闻内容';

CREATE TABLE IF NOT EXISTS `huoniao_article_breakup_table` (`id` INT(11) NOT NULL AUTO_INCREMENT, `table_name` VARCHAR(255) NULL COMMENT '表名', `begin_id` INT(11) NULL COMMENT '开始id', PRIMARY KEY (`id`)) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='分表记录';

CREATE TABLE IF NOT EXISTS `huoniao_article_historyclick` (`id` INT(11) NOT NULL AUTO_INCREMENT, `uid` INT(10) NOT NULL DEFAULT '0' COMMENT '浏览者id', `fuid` INT(10) NOT NULL DEFAULT '0' COMMENT '发布者id', `aid` INT(10) NOT NULL DEFAULT '0' COMMENT '信息id', `module` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '模块', `module2` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '二级类目', `date` CHAR(20) NOT NULL DEFAULT '' COMMENT '时间', PRIMARY KEY (`id`), KEY `uid` (`uid`), KEY `fuid` (`uid`)) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='资讯浏览足迹';

CREATE TABLE IF NOT EXISTS `huoniao_article_pagecount_cache` (`id` INT(11) NOT NULL AUTO_INCREMENT, `key` TEXT NULL, `value` INT(30) NULL, `update_at` INT(30) NULL, PRIMARY KEY (`id`)) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='资讯列表count缓存表';

CREATE TABLE IF NOT EXISTS `huoniao_article_selfmedia` (`id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT, `cityid` INT(10) NOT NULL DEFAULT '0' COMMENT '城市', `userid` INT(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '用户id', `type` INT(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '入驻类型', `ac_name` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '自媒体名称', `ac_profile` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '自媒体介绍', `ac_field` INT(2) UNSIGNED NOT NULL DEFAULT '0' COMMENT '自媒体领域', `ac_addrid` INT(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '自媒体所在地', `ac_photo` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '头像', `mb_name` VARCHAR(30) NULL DEFAULT '' COMMENT '主体名称', `mb_code` VARCHAR(18) NULL DEFAULT '' COMMENT '主体社会信用代码', `mb_level` INT(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '主体机构级别', `mb_type` INT(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '主体机构类型', `mb_license` VARCHAR(255) NULL DEFAULT '' COMMENT '主体执照或证书', `op_name` VARCHAR(200) NOT NULL DEFAULT '' COMMENT '运营者姓名', `op_idcard` VARCHAR(200) NOT NULL DEFAULT '' COMMENT '运营者身份证号', `op_idcardfront` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '运营者持身份证照片', `areaCode` VARCHAR(10) NOT NULL DEFAULT '' COMMENT '区号', `op_phone` VARCHAR(100) NOT NULL DEFAULT '' COMMENT '运营者联系手机', `op_email` VARCHAR(150) NOT NULL DEFAULT '' COMMENT '运营者联系邮箱', `op_authorize` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '运营者机构授权证书', `org_major_license_type` INT(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '专业资质类型', `org_major_license` VARCHAR(255) NULL DEFAULT '' COMMENT '专业资质', `outer` VARCHAR(255) NULL DEFAULT '' COMMENT '外平台信息', `prove` VARCHAR(255) NULL DEFAULT '' COMMENT '证明材料', `state` INT(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '状态', `editstate` INT(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '资料修改状态', `pubdate` INT(10) NOT NULL DEFAULT '0' COMMENT '入驻时间', `editlog` TEXT NULL COMMENT '修改记录', `click` INT(10) NOT NULL DEFAULT '0' COMMENT '浏览次数', `weight` INT(10) NOT NULL DEFAULT '0' COMMENT '排序', `ac_banner` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '幻灯', PRIMARY KEY (`id`), KEY `