CREATE TABLE IF NOT EXISTS `huoniao_article_selfmedia_arctype` (`id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT, `parentid` INT(10) NOT NULL DEFAULT '0' COMMENT '父级id', `aid` INT(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '自媒体id', `typename` CHAR(30) NOT NULL DEFAULT '' COMMENT '领域', `weight` INT(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '排序', `pubdate` INT(10) NOT NULL DEFAULT '0' COMMENT '创建时间', `jump` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '跳转链接', `icon` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '图标', PRIMARY KEY (`id`)) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='新闻自媒体自定义分类';

