CREATE TABLE IF NOT EXISTS `huoniao_article_zhuanti` (`id` SMALLINT(5) NOT NULL AUTO_INCREMENT, `parentid` INT(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '父级id', `typename` CHAR(200) NOT NULL DEFAULT '' COMMENT '分类名称', `description` VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'SEO描述', `weight` SMALLINT(5) UNSIGNED NOT NULL DEFAULT '50' COMMENT '排序', `pubdate` INT(10) NOT NULL DEFAULT '0' COMMENT '创建时间', `state` TINYINT(1) NOT NULL DEFAULT '0' COMMENT '状态', `flag_r` TINYINT(1) NOT NULL DEFAULT '0' COMMENT '推荐', `flag_h` TINYINT(1) NOT NULL DEFAULT '0' COMMENT '头条', `litpic` CHAR(100) NOT NULL DEFAULT '' COMMENT '图片', `click` INT(10) NOT NULL DEFAULT '0' COMMENT '浏览次数', `banner_large` CHAR(255) NOT NULL DEFAULT '' COMMENT 'pc大banner', `banner_small` CHAR(255) NOT NULL DEFAULT '' COMMENT 'pc小banner', `typeid` INT(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '分类id', PRIMARY KEY (`id`)) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='新闻专题';

